"""matplotlib._enums — enums for cap, join, and fill styles.

Upstream uses real :class:`enum.Enum` subclasses (so isinstance checks
and ``.value`` access work). Mirroring that contract.
"""

from enum import Enum


class JoinStyle(str, Enum):
    """Define how the joins between line segments are drawn.

    Mirrors matplotlib's :class:`~matplotlib.JoinStyle` — three legal
    values, all inheriting from :class:`str` so old code that compares
    against the string name (``"miter"`` etc.) still works.
    """

    miter = 'miter'      # Sharp corner — extends the outer edge.
    round = 'round'      # Rounded corner.
    bevel = 'bevel'      # Beveled corner — fills the wedge with a flat edge.

    @classmethod
    def demo(cls):
        """Names of all join styles, in their canonical order."""
        return [s.name for s in cls]


class CapStyle(str, Enum):
    """Define how the line endings are drawn.

    Mirrors matplotlib's :class:`~matplotlib.CapStyle`. As with JoinStyle,
    each value inherits from str for backward-compat with code that
    passes raw strings.
    """

    butt = 'butt'              # Square cap flush with the endpoint.
    projecting = 'projecting'  # Square cap that extends past the endpoint.
    round = 'round'            # Rounded cap.

    @classmethod
    def demo(cls):
        return [s.name for s in cls]
